Subroutine Double(x As Integer) As Integer
  Return x * 2;
EndSubroutine

Algorithm Main
  Write Double(21);
EndAlgorithm

Subroutine Average(a As Integer, b As Integer, c As Integer) As Real
  Return (a + b + c) / 3;
EndSubroutine

Subroutine Estado(average As Real) As String
  If average >= 6 Then
    Return "passed";
  EndIf
  Return "failed";
EndSubroutine

Algorithm ReportCard
  Define name As String;
  Define m1, m2, m3 As Integer;
  Define bestName As String <- "";
  Define bestAverage As Real <- -1.0;
  For i <- 1 To 4 Do
    Read name;
    Read m1;
    Read m2;
    Read m3;
    Define avg As Real <- Average(m1, m2, m3);
    Write name, ": ", avg, " ", Estado(avg);
    If avg > bestAverage Then
      bestAverage <- avg;
      bestName <- name;
    EndIf
  EndFor
  Write "Best average: ", bestName;
EndAlgorithm

Subroutine Average(a As Integer, b As Integer, c As Integer) As Real
  Return (a + b + c) / 3;
EndSubroutine

Subroutine Estado(average As Real) As String
  If average >= 6 Then
    Return "passed";
  EndIf
  Return "failed";
EndSubroutine

Algorithm Tests
  Write Average(6, 6, 6);
  Write Estado(6.0);
  Write Estado(5.9);
EndAlgorithm
